int FFScanner::iInputCode(char *buffer, int &result, int max_size)
{
  if( iIn->eof() || iIn->fail() )
    {
      result = YY_NULL;
    } 
  else 
    {
      iIn->getline(buffer, max_size - 2, '\n');
      result = strlen (buffer);
      buffer[result] = '\n';
      buffer[result+1] = 0;
      result += 1;
      if( iIn->bad() ) 
	{
	  YY_FATAL_ERROR( "read() in flex scanner failed" );
	}
    }
  return(result);
}

String FFScanner::escapesym (char c)
{
  String ret;
  
  switch (c)
    {
    case '\\': ret = "\\"; break;
    case '\"': ret = "\""; break;
    default: ret = c;
    }
  return ret;
}

void FFControl::PrintError(char *s )
{
  std::ostringstream tmpS;
  tmpS << s << " in line " << lineCount+1 ;
  ffError(USER_ERROR, tmpS.str().c_str());
}

